import { cx } from '~/lib/cx.ts'
import type { HTMLAttributes } from '~/lib/types.ts'
import styles from './overlay.module.scss'

export interface OverlayProps extends HTMLAttributes<HTMLDivElement> {
  tone?: 'dark' | 'light'
}

/** Dimmed backdrop for dialogs and sheets. */
export function Overlay({ tone = 'dark', className, ...props }: OverlayProps) {
  return (
    <div
      aria-hidden="true"
      className={cx(styles.root, styles[tone], className)}
      {...props}
    />
  )
}

@use 'styles' as vz;

.root {
  position: fixed;
  inset: 0;
  z-index: vz.z('overlay');
}

.dark {
  background: rgb(0 0 0 / 0.5);
}

.light {
  background: rgb(255 255 255 / 0.6);
}
